UPDATE tasks SET title='Decode frames using the shared result contract',description='Local preview example: Protocol frame decoding uses the Core result and error types.',acceptance_criteria='The frame decoder returns the shared Core result type and has malformed-frame coverage. Depends on demo-open-069.' WHERE id='demo-open-066';
UPDATE tasks SET title='Build a deterministic protocol fixture runner',description='Local preview example: a standalone Tooling task that validates checked-in protocol fixtures.',acceptance_criteria='The fixture runner produces deterministic results and does not require another module task.' WHERE id='demo-open-073';
UPDATE tasks SET title='Define the transport connector interface',description='Local preview example: Networking defines the connector boundary consumed by Runtime sessions.',acceptance_criteria='The connector contract exposes connection lifecycle outcomes needed by Runtime integration.' WHERE id='demo-open-071';
UPDATE tasks SET title='Integrate transport connectors into sessions',description='Local preview example: Runtime session setup consumes the Networking connector interface.',acceptance_criteria='Runtime session setup uses the connector contract and covers connect, close, and failure paths. Depends on demo-open-071.' WHERE id='demo-open-064';
UPDATE tasks SET title='Dispatch decoded protocol messages',description='Local preview example: Runtime dispatch consumes frames decoded by Protocol.',acceptance_criteria='Runtime dispatch handles decoded messages and malformed-frame errors. Depends on demo-open-066.' WHERE id='demo-open-072';
