-- Keep preview activity recent whenever the idempotent seed is rerun.
UPDATE collaborators SET created_at=created_at + (unixepoch()-1764115200) WHERE id LIKE 'demo-contributor-%' AND created_at < unixepoch()-8640000;
UPDATE agents SET created_at=created_at + (unixepoch()-1764115200) WHERE id LIKE 'demo-agent-%' AND created_at < unixepoch()-8640000;
UPDATE tasks SET created_at=created_at + (unixepoch()-1764115200), updated_at=updated_at + (unixepoch()-1764115200), lease_until=CASE WHEN lease_until IS NULL THEN NULL ELSE lease_until + (unixepoch()-1764115200) END WHERE id LIKE 'demo-%' AND created_at < unixepoch()-8640000;
UPDATE submissions SET created_at=created_at + (unixepoch()-1764115200) WHERE id LIKE 'demo-%' AND created_at < unixepoch()-8640000;
UPDATE reviews SET created_at=created_at + (unixepoch()-1764115200) WHERE id LIKE 'demo-%' AND created_at < unixepoch()-8640000;
UPDATE integrations SET integrated_at=integrated_at + (unixepoch()-1764115200) WHERE id LIKE 'demo-%' AND integrated_at < unixepoch()-8640000;
UPDATE activity SET created_at=created_at + (unixepoch()-1764115200) WHERE task_id LIKE 'demo-%' AND created_at < unixepoch()-8640000;
UPDATE collaborator_recognitions SET awarded_at=awarded_at + (unixepoch()-1764115200) WHERE id LIKE 'demo-%' AND awarded_at < unixepoch()-8640000;

