WITH integrations_ranked AS (SELECT i.*,ROW_NUMBER() OVER(ORDER BY i.id) AS rn FROM integrations i WHERE i.id LIKE 'demo-integration-%')
INSERT INTO activity (id,task_id,actor_id,action,details_json,created_at)
SELECT printf('demo-event-%03d',i.rn),i.task_id,i.integrated_by,'task.integrated',
 json_object('submissionId',i.submission_id,'commitSha',i.submitted_commit_sha,'mergeCommitSha',i.merge_commit_sha),i.integrated_at
FROM integrations_ranked i;
WITH integrations_ranked AS (SELECT i.*,s.agent_id,ROW_NUMBER() OVER(ORDER BY i.id) AS rn FROM integrations i JOIN submissions s ON s.id=i.submission_id WHERE i.id LIKE 'demo-integration-%')
INSERT INTO activity (id,task_id,actor_id,action,details_json,created_at)
SELECT printf('demo-event-%03d',100+i.rn),i.task_id,a.collaborator_id,'task.claimed',json_object('agentId',a.id,'agentName',a.name),i.integrated_at-7200
FROM integrations_ranked i JOIN agents a ON a.id=i.agent_id;
WITH integrations_ranked AS (SELECT i.*,s.agent_id,s.id AS submission_id,s.commit_sha,s.pull_request_url,ROW_NUMBER() OVER(ORDER BY i.id) AS rn FROM integrations i JOIN submissions s ON s.id=i.submission_id WHERE i.id LIKE 'demo-integration-%')
INSERT INTO activity (id,task_id,actor_id,action,details_json,created_at)
SELECT printf('demo-event-%03d',200+i.rn),i.task_id,a.collaborator_id,'task.submitted',
 json_object('submissionId',i.submission_id,'commitSha',i.commit_sha,'pullRequestUrl',i.pull_request_url,'agentId',a.id,'agentName',a.name),i.integrated_at-3600
FROM integrations_ranked i JOIN agents a ON a.id=i.agent_id;
INSERT INTO activity (id,task_id,actor_id,action,details_json,created_at)
SELECT printf('demo-event-%03d',300+CAST(substr(t.id,12,3) AS INTEGER)-80),t.id,a.collaborator_id,'task.claimed',json_object('agentId',a.id,'agentName',a.name),t.updated_at
FROM tasks t JOIN agents a ON a.id=t.assignee_agent_id WHERE t.id BETWEEN 'demo-task-081' AND 'demo-task-089' AND t.status='claimed';
INSERT INTO activity (id,task_id,actor_id,action,details_json,created_at)
SELECT printf('demo-event-%03d',400+CAST(substr(t.id,12,3) AS INTEGER)-90),t.id,a.collaborator_id,'task.submitted',
 json_object('submissionId',s.id,'commitSha',s.commit_sha,'pullRequestUrl',s.pull_request_url,'agentId',a.id,'agentName',a.name),s.created_at
FROM submissions s JOIN tasks t ON t.id=s.task_id JOIN agents a ON a.id=s.agent_id WHERE t.id BETWEEN 'demo-task-091' AND 'demo-task-095';
INSERT INTO activity (id,task_id,actor_id,action,details_json,created_at)
SELECT printf('demo-event-%03d',500+ROW_NUMBER() OVER(ORDER BY r.id)),s.task_id,r.reviewer_id,'submission.accepted',
 json_object('submissionId',s.id,'decision',r.decision),r.created_at
FROM reviews r JOIN submissions s ON s.id=r.submission_id WHERE r.id IN ('demo-review-094','demo-review-095');
-- Keep legacy local workflow fixtures from placing activity in the future.
UPDATE activity SET created_at=unixepoch()-900 WHERE task_id IN ('demo-open-069','demo-open-070') AND created_at>unixepoch();
